      "details": "仅在主体头部佩戴头饰物件，不得放置于身体其他部位"
    },
    "key_details": "强调单一醒目造型，避免过度臃肿，宽大剪裁与利落剪裁形成对比，显著品牌标识，通过纯粹的材质质感而非阴影呈现不同面料的厚重感"
  },
  "footwear_focus": {
    "models": ["Nike SB Dunk", "Off-White™ x Nike deconstructed models", "Converse Chuck 70 premium high-top", "Vans Vault Slip-On", "Adidas Samba", "New Balance 327", "ASICS Onitsuka Tiger Sneakers"],
    "details": "是主体脚上唯一的物件，高度可见且崭新无瑕，构成动态动作的锚点"
  },
  "visual_color_treatment": {
    "base_spectrum": "纯粹、毫不妥协的黑白，伴随超深浓郁的黑色色调",
    "blend_mode": "极端质地对比与无影光谱照明的融合",
    "palette_components": {
      "rich_matte_black": "纯吸光的羊毛、牛仔布与厚棉，类似Vantablack的密度，通过表面质感呈现压榨般的深黑以达到最大深度",
      "high_sheen_monochrome": "抛光皮革、反光技术尼龙、光亮聚合物捕捉纯白镜面高光而不投射阴影",
      "monochrome_solarization": "幽灵般的光谱边缘光，反转的亮度高光定义褶皱与轮廓，鲜明、超高对比的发光边缘"
    }
  },
  "lighting_dynamics": "平坦、高调、全向漫散射的工作室照明。主体、地面或背景无任何投射阴影。形体与深度被压平，完全依赖光滑表面、压榨般的浓黑与发光的太阳化边缘轮廓之间的鲜明对比来定义。"
}

