      "clothing": "一件简单、贴身的黑色低圆领背心或连体衣。",
      "accessories": {
        "necklaces": "叠戴的金色项链，包括一条粗链节链和一条较细的链，较细的链上有金色独角兽或马的吊坠。",
        "earrings": "粗厚的金色大圈耳环。",
        "wristwear": "右手腕戴多条粗金手镯；左手腕戴一条珍珠手链。",
        "rings": "手指上戴着金戒指。"
      }
    },
    "environment": {
      "setting": "灯光昏暗的高档餐厅或酒吧内景。",
      "background_elements": "左侧有木质百叶窗或木质面板。背景有暖色的模糊串灯（焦外光斑）和吊灯。顶部有些许垂挂绿植。",
      "atmosphere": "亲密、时髦的夜生活氛围。"
    },
    "lighting": {
      "type": "机内直接闪光灯结合暖色环境背景光。",
      "effect": "高对比。主体被强烈照亮，脸部（额头、颧骨、下巴）和酒杯上可见镜面高光，背景因此落入阴影。"
    },
    "camera_technical": {
      "style": "闪光摄影美学（在网红/社交媒体文化中流行）。",
      "focus": "对主体的脸部和首饰有清晰的对焦，浅景深使背景的客人和灯光模糊。",
      "quality": "拟真摄影，高分辨率，4K。"
    }
  },
  "prompt_construction": {
    "full_prompt": "一张超写实的闪光摄影人像，表现一位拥有金色手刷挑染（balayage）头发的迷人年轻女性，坐在灯光昏暗、时髦的餐厅内。她穿着黑色低圆领紧身背心，佩戴大量金色首饰，包括带有吊坠的叠戴项链、粗大的圈形耳环和粗金手镯。她将一杯红酒靠近光泽的嘴唇，侧着头，表情诱人。她的妆容湿润并带古铜色调，带有翘翼眼线。背景有木质百叶窗、昏暗的氛围和暖色的焦外串灯。灯光为直接强烈的闪光风格，突出她的皮肤质地和酒杯。使用高端便携数码相机拍摄，35mm 镜头，高对比，流行的社交媒体美学，8K 分辨率。"
  }
}

