      },
      "makeup": "妆容：韩流/抖音风格：白皙底妆、柔和渐变的红唇、淡淡腮红、明显的眼线。"

"2x2 照片拼贴（四格网格）。",
    },
    "environment_and_props": {
      "studio_setting": "高调摄影棚。",
      "background": "无缝明亮白色背景布。",
      "flooring": "光亮的黑色反光地面（能清晰反射鞋和腿部）。",
      "props": "一束黑色氦气气球（哑光和亮面混合），在左上角可见，并在其他画格的地面上散落。"
    },
    "panel_pose_breakdown": {
      "panel_1_top_left": {
        "framing": "取景：大腿以上的半身镜头。",
        "pose": "姿势：站直。左手轻靠左侧面颊（手掌朝向下颌）。右臂自然垂放在身侧。头略微倾斜。",
        "gaze": "目光：直视镜头，带着温柔微笑。",
        "prop_placement": "道具位置：黑色气球漂浮在左上角。"
      },
      "panel_2_top_right": {
        "framing": "取景：全身，坐姿。",
        "pose": "姿势：坐在地上，双膝屈起并向上，双脚平放于地。双手松散地放在双腿之间的地面上或放在小腿上。",
        "gaze": "目光：直视，表情中性。",
        "details": "细节：构图对称。"
      },
      "panel_3_bottom_left": {
        "framing": "取景：全身，坐姿角度。",
        "pose": "姿势：坐在地上，躯干向后倾，用双臂向后伸直支撑体重。双腿屈曲，一侧膝盖比另一侧更高。",
        "gaze": "目光：微微侧视，带有酷感态度。"
      },
      "panel_4_bottom_right": {
        "framing": "取景：全身，坐姿。",
        "pose": "姿势：双腿向一侧弯曲坐着。左手抬起，若有所思地触摸下巴/颈部区域。右臂向后伸出支撑。",
        "gaze": "目光：直视镜头，带着浅浅的得意微笑。"
      }
    },
    "camera_technical_values": {
      "lens": "镜头：50mm 至 85mm（标准人像镜头）。",
      "aperture": "光圈：f/8.0（景深较深，使主体在白色背景下整体清晰）。",
      "shutter_speed": "快门速度：1/160s（工作室同步）。",
      "iso": "ISO：100（画面干净、无噪点）。",
      "lighting_setup": "灯光设置：柔光箱照明。前方大面积漫射光源，营造无阴影、对脸部有修饰效果的照明（“美容光”）。",
      "contrast": "对比度：黑色服装与纯白背景之间形成高对比。"
    }
}

