    "视觉结构": "多个同一主体的照片剪贴，以混乱但协调的布局排列在复古质感背景上。每个剪贴都带有厚实的白色描边，像贴纸一样。"
  },
  "主体细节": {
    "人群特征": "年轻亚洲女性（K-pop偶像美学），白皙皮肤，精致五官。",
    "发型": "长发，丰盈，深色波浪发，带空气刘海。在一个画面中，她佩戴一个小白色丝带夹。",
    "服装": "黑色亮片/装饰短款上衣（文胸式），深色牛仔裤。",
    "妆容": "桃色腮红，光泽唇彩，柔和眼线。"
  },
  "姿势分镜面板": {
    "面板_1_顶部中央": "肖像照。主体直视/略微低头，手抚发，肘部抬起。背景为模糊城市景观。",
    "面板_2_底部右侧": "坐姿/斜躺姿势。主体向后靠，一臂支撑身体，冷静地看向镜头。穿着牛仔裤。",
    "面板_3_中部右侧": "越肩拍摄。主体回头望向镜头，眼神柔和，手臂抬起触碰头部。",
    "面板_4_底部左侧": "特写肖像。主体侧脸望向一边，佩戴白色蝴蝶结发夹。",
    "面板_5_顶部左侧": "胸部以上特写。主体目光看向画外，表情梦幻。"
  },
  "图形元素与叠加": {
    "背景质感": "复古报纸印刷文字（棕褐色/米色调）。",
