{
  "类型": "2x2 照片拼贴（4 格网格）。",
  "主题": "热带海滩度假拍摄。",
  "布局": "在白色沙滩上同一主体的四张不同镜头。",
  "一致性": "所有面板中主体、服装和地点一致。",
  "主体细节": {
    "人口统计": "年轻的亚洲女性，肤色白皙。",
    "发型": "长黑发，扎成两股松散的辫子（双马尾）。",
    "服装": {
      "泳装": "黑色连体泳衣（monokini），中间有镂空且领口深V。",
      "下装": "白色超迷你裙或围腰，系在腰间。",
      "配饰": "宽檐草帽、长珍珠项链（系在帽子或眼镜上）、金色手镯式臂环、耳后夹着的大黄花。"
    }
  },
  "环境": {
    "地点": "阳光明媚的热带海滩。",
    "元素": "白色沙滩、绿松石色海水、远处的绿色岛屿/小山、蓝天白云。",
    "道具": "红白条纹手提袋/沙滩毛巾。"
  },
  "面板分解_姿势": {
    "面板1_左上": {
      "取景": "低角度，全身。",
      "姿势": "站立，微向后仰，仰望太阳。手持条纹包。",
      "背景": "顶部可见棕榈树叶，蓝天。"
    },
    "面板2_右上": {
      "取景": "高角度/俯拍。",
      "姿势": "仰躺在沙滩上，双腿伸展（一膝抬起），头转向一侧朝向镜头。下面铺着红色条纹毛巾。",
      "背景": "沙子纹理和靠近水边的一艘红色小船。"
    },
    "面板3_左下": {
      "取景": "自拍角度/特写。",
      "姿势": "主体伸手持相机（手臂伸出），直视镜头。头部倾斜，展示帽子和花朵。",
      "背景": "以蓝天为主。"
    },
    "面板4_右下": {
      "取景": "中景，坐姿。",
      "姿势": "坐在沙滩上，调整泳衣肩带或项链。自然地低头或侧看。",
      "背景": "海平线和远处的山脉。"
    }
  },
  "相机技术参数": {
    "镜头": "广角（16mm - 24mm），用于自拍和低角度拍摄以强调身高和背景景观。",
    "光圈": "f/8.0（大景深，保持明亮阳光背景清晰）。",
    "快门速度": "1/500s（明亮日光）。",
    "ISO": "ISO 100。",
    "光照": "强烈自然阳光。高对比、清晰的阴影、色彩鲜艳。"
  }
}

