{
  "project_configuration": {
    "title": "电影式养生：桑拿肖像",
    "version": "2.0_高保真",
    "output_parameters": {
      "aspect_ratio": "9:16",
      "resolution": "8K 超高清",
      "color_space": "DCI-P3",
      "style_preset": "超写实照相风格",
      "rendering_engine": "Octane Render / 虚幻引擎 5.4 路径追踪"
    }
  },
  "subject_composition": {
    "identity": {
      "resemblance": "相似于悉尼·斯威尼",
      "age_range": "二十出头",
      "expression": "宁静、内省、迷人、直视镜头",
      "skin_tone": "白皙、象牙色、透亮带光泽的肤质"
    },
    "anatomical_precision": {
      "micro_details": "可见的皮肤毛孔、细小绒毛、逼真的皮肤质地、皮下散射（SSS）、锁骨和额头上的微小晶莹水滴。",
      "eyes": "深榛色、复杂的虹膜纹理、清晰的高光反射出温暖桑拿内部。",
      "lips": "柔和粉色、湿润、微微张开，因湿度而呈高光光泽。",
      "hair": "长及肩的金发，湿润造型，潮湿发丝贴附于皮肤，深金色发根，高光泽反射。"
    },
    "attire_and_fabric": {
      "primary_garment": "高纹理白色棉质浴巾",
      "fabric_details": "可见绒圈（毛巾绒）、厚重面料手感、潮湿处呈现更深的白色、复杂的编织纹理、柔软的磨损边缘。"
    },
    "pose_and_dynamics": {
      "position": "优雅地坐在中层雪松长凳上，脚踝交叉。",
      "body_language": "微微向前倾以制造纵深感，肩部放松，姿势自然，双手轻放在木面上。"
    }
  },
  "environment_design": {
    "setting": "超豪华传统芬兰桑拿",
    "interior_materials": {
      "wood": "抛光的西部红雪松，横向木板，可见木纹、结疤以及热致油光。",
      "elements": "不锈钢加热炉内的热桑拿石（背景），上升的热气迷雾。"
    },
    "atmospheric_effects": {
      "steam": "缥缈的盘旋蒸汽、体积雾、厚重湿气、饱含水汽的空气。",
      "haze": "背景轻微虚化，金色时段的光辉透过蒸汽颗粒滤出。"
    }
  },
  "lighting_and_optics": {
    "lighting_setup": {
      "type": "温暖的漫射环境光",
      "primary_source": "隐藏在长凳下的 LED 灯带，形成柔和的底部泛光。",
      "secondary_source": "自上而下的暖色聚光灯（3200K）。",
      "shadows": "阴影柔和、漫射，无硬边。"
    },
    "optical_settings": {
      "lens": "35mm 定焦镜头，广角且畸变最小。",
      "aperture": "f/1.8 光圈制造浅景深（背景散景）。",
      "focus": "将焦点精确对准被摄者眼睛，向肩部和环境逐渐虚化。"
    }
  },
  "technical_post_processing": {
    "quality_enhancements": [
      "照片级超真实杰作",
      "光线追踪反射",
      "全局光照",
      "变形镜头光斑（微妙）",
      "高动态范围（HDR10+）",
      "16 位色深"
    ],
    "color_grading": {
      "palette": "温暖的琥珀色、深褐色、纯净的白色、柔和的肤色。",
      "vibe": "电影感、亲密、豪华水疗、高端时尚编辑风格。"
    }
  }
}

