{
  "album_malomat": {
    "location": "Paris, France",
    "mausam": "Sardiyan aur barfbari",
    "markazi_kirdar": "Ek naujawan khatoon"
  },
  "tasveeron_ki_tafseel": [
    {
      "tasvir_id": "01",
      "manzar_kashi": {
        "mahaul": "Pur-sukoon aur romantic",
        "waqt": "Sham ka dhundalka",
        "background": "Eiffel Tower halka sa numayan hai aur peechay cafe ki sunhari roshniyan (bokeh effect) ek garmi ka ehsas dila rahi hain."
      },
      "kirdar_ka_huliya": {
        "chehra": "Saaf rangat, halka makeup, aur pursukoon nazrein jo aasman ki taraf hain.",
        "libas": {
          "topi": "Siyah rang ki oon (wool) ki beret jis par barf giri hui hai.",
          "scarf": "Bhure (beige) rang ka mota knitted scarf.",
          "coat": "Siyah rang ka sardiyon ka heavy coat."
        },
        "baal": "Saliqe se sanware hue aur halkay bikhre hue."
      }
    },
    {
      "tasvir_id": "02",
      "manzar_kashi": {
        "mahaul": "Zyada daramaee (dramatic) aur thanda",
        "waqt": "Raat ka waqt",
        "background": "Roshniyan pehle se zyada dhundli hain aur barf ke gaale zyada wazeh dikhayi de rahe hain."
      },
      "kirdar_ka_huliya": {
        "chehra": "Chehre par nami aur geelapan hai, ankhon mein thoda jazbati pan hai.",
        "libas": {
          "topi": "Is tasvir mein topi nahi pehni hui.",
          "scarf": "Wohi beige scarf lekin barf se zyada bhara hua.",
          "coat": "Siyah coat jo geela mehsoos ho raha hai."
        },
        "baal": "Barf aur nami ki wajah se geele aur bikhre hue, jo mausam ki shidat ko zahir karte hain."
      }
    }
  ]
}

