{
  "album_malomat": {
    "location": "巴黎，法国",
    "mausam": "冬季与降雪",
    "markazi_kirdar": "一位年轻女士"
  },
  "tasveeron_ki_tafseel": [
    {
      "tasvir_id": "01",
      "manzar_kashi": {
        "mahaul": "宁静且浪漫",
        "waqt": "黄昏的余晖",
        "background": "埃菲尔铁塔若隐若现，后方咖啡馆的金色灯光（散景效果）带来一丝温暖的感觉。"
      },
      "kirdar_ka_huliya": {
        "chehra": "肤色清晰，淡妆，平静的目光望向天空。",
        "libas": {
          "topi": "黑色羊毛贝雷帽，上面落着雪。",
          "scarf": "米色的厚实针织围巾。",
          "coat": "黑色的冬季厚外套。"
        },
        "baal": "头发整理得整洁，但略显松散。"
      }
    },
    {
      "tasvir_id": "02",
      "manzar_kashi": {
        "mahaul": "更戏剧化且寒冷",
        "waqt": "夜间",
        "background": "灯光比之前更模糊，落雪的轮廓更加清晰可见。"
      },
      "kirdar_ka_huliya": {
        "chehra": "脸上有湿润和潮湿感，眼神带有些许情绪。",
        "libas": {
          "topi": "这张照片中没有戴帽子。",
          "scarf": "仍是那条米色围巾，但上面积了更多雪。",
          "coat": "黑色外套感觉有些潮湿。"
        },
        "baal": "由于雪和湿度，头发湿漉且凌乱，体现出天气的严酷。"
      }
    }
  ]
}

