  "prompt": "一个高端极简护肤品摄影场景，主体为一个打开的白色化妆罐，罐身标注 'Sealine Serum'。罐子置于一块光滑、浅色的石头上，石头部分浸没在清澈的浅水中。罐中膏霜呈柔和有光泽的漩涡状，质地洁净、丝滑。石头周围泛起轻柔的水波，形成自然的光折射和水下炫光图案。细小水珠与微微飞溅的水花增添新鲜感与动感。整体氛围宁静、干净、自然，唤起纯净、补水与沉静奢华的感觉。色彩以冷调清透为主，主打柔和白色、浅蓝色与石材中性色。光线为明亮的漫射日光，带有柔和高光和最小阴影，强调质感、湿润感与真实性。构图居中且平衡，景深浅，背景柔和虚化，呈现高端化妆品广告风格。超真实、摄影级、编辑质量的产品拍摄。",
  "negative_prompt": "强烈阴影、污浊水、杂乱背景、塑料质感、低分辨率、过度锐化、不真实反射、强烈色偏、文字伪影、水印、标志失真、凌乱的膏霜表面",
  "style": "奢华护肤品广告",
  "camera": {
    "type": "单反相机（DSLR）",
    "lens": "90mm 微距镜头",
    "aperture": "f/5.6",
    "iso": 100,
    "shutter_speed": "1/250"
  },
  "lighting": {
    "type": "自然漫射日光",
    "direction": "顶部和侧面",
    "contrast": "低到中等",
    "temperature": "冷中性"
  },
  "composition": {
    "framing": "以产品为中心的构图",
    "angle": "略微抬高（轻微俯视）",
    "orientation": "纵向",
    "depth_of_field": "景深浅，背景柔和虚化"
  },
  "quality": {
    "resolution": "8K",
    "detail": "超细纹理细节",
    "sharpness": "高",
    "realism": "摄影级逼真"
  }
}

