items.contentChinese:
{
  "image_generation_request": {
    "subject": "[PRODUCT]",
    "product_finish": {
      "primary": "哑光黑，带有微弱的光吸收效果",
      "secondary": "抛光金属银，具有镜面般的反射",
      "treatment": "二色调 — 哑光黑机身配以金属银点缀、饰边、边缘或面板镶嵌"
    },
    "composition": {
      "placement": "正中央，完整视图，悬浮于折叠表面环境中",
      "scale": "产品占画面约30-40%",
      "constraints": [
        "产品必须完全可见，不得被裁切",
        "不得使用底座、支架、平台或地面平面",
        "表面褶皱框架产品但不得遮挡超过10%",
        "产品是场景中最清晰的元素"
      ]
    },
    "background_environment": {
      "description": "一个连续的起伏表面填满整个画面，自身折叠并围绕自身形成大而富有体积的波浪 —— 像一大片褶皱的金属丝绸或一整块经过柔和扭曲与悬垂的机械加工金属面板。它不是多条独立的缎带或线束。它是一个连接在一起的单一表面。",
      "base_color": "[INSERT DEEP BACKGROUND COLOR 可见于褶皱处 — 例如: 纯黑, 午夜海军蓝]",
      "surface_color_1": "[INSERT GRADIENT COLOR A — 例如: 柔和薰衣草, 温暖铜色, 珍珠玫瑰]",
      "surface_color_2": "[INSERT GRADIENT COLOR B — 例如: 深靛蓝, 钴蓝, 紫罗兰]",
      "color_behavior": "两种颜色在单一表面上以平滑连续的渐变混合，随着表面曲率和光线角度发生变化。表面朝向光源的区域呈现 color_1，背光弯曲处过渡为 color_2。过渡无硬边或条纹，衔接自然。",
      "surface_texture": {
        "type": "表面压纹为细并行肋纹 — 类似唱片的凹槽或精致百褶的手风琴面料",
        "rib_description": "极其细密、均匀且紧密排列的平行细线，沿表面流动方向延伸。肋纹是表面纹理，而非独立物体。它们在每条微小脊线上捕捉光线，形成细微的波纹效果。",
        "rib_density": "非常高 — 约每英寸表面可见50-100条线，形成密集的线性纹理",
        "rib_depth": "浅 — 肋纹是细微的表面细节，而非深切口。在表面上产生温和的高光与阴影交替"
      },
      "surface_form": {
        "fold_style": "大型、平滑、有体积的褶皱，像垂坠的厚重丝绸 — 宽阔的扫动曲线与柔和扭转",
        "fold_count": "可见3-5个主要褶皱，每个都宽大而大气，不是许多小而纠结的带状褶皱",
        "fold_behavior": "褶皱彼此柔和重叠，互相掖入和翻越，过渡平滑。褶皱交会处形成深而柔和的阴影沟壑",
        "tension": "表面在每个褶皱上显得平滑且绷紧，无皱褶或揉皱 — 如绸缎覆盖在弯曲曲面上被拉紧的效果",
        "edges": "无可见边缘 — 表面似乎向画外延伸，仿佛我们所见只是一个无限垂坠表面的近景部分"
      },
      "material": {
        "finish": "缎面金属 — 介于哑光与镜面之间的柔和拉丝金属光泽。表面具有珠光特性，颜色随观察角度变化",
        "light_interaction": "每条肋纹脊顶呈现柔和的镜面高光，肋纹谷处有轻柔阴影，整体在宽阔褶皱上形成若隐若现的线性闪烁感"
      }
    },
    "lighting": {
      "type": "柔和、漫射且有方向性 — 仿佛来自左上方的大型柔光箱照明，制造出暖到冷的渐变效果",
      "shadow_behavior": "褶皱沟壑处有深而柔和的阴影，逐渐衰减 — 无硬边阴影",
      "highlight_behavior": "在褶皱峰部有宽而柔和的高光，肋纹纹理带来细微线性闪烁",
      "restrictions": "不得出现可见光源、不允许镜头光斑、不允许出现摄影棚设备的反射"
    },
    "style": {
      "aesthetic": "参数化设计艺术、计算雕塑、抽象奢华",
      "mood": "奢华、顺滑、触感强、顶级产品展示",
      "critical_note": "背景必须看起来像单一连续的折叠金属表面，带有细微肋纹纹理 — 不能像多条独立的缎带、电缆、线或捆绑在一起的条状物。请想象一整块细腻百褶的金属片被优雅地悬垂与折叠。"
    },
    "technical_specs": {
      "quality": "8k 分辨率，极致表面纹理细节，产品对焦异常锐利",
      "render_style": "写实的3D渲染，Octane 或 Redshift 级别质量",
      "aspect_ratio": "1:1 方形",
      "exclusions": "背景中不得出现文字、水印、标志、额外道具、镜头光斑、摄影棚设备、平面表面、任何地面、独立缎带、线束或绳状形式"
    }
  }
}

