      "左侧有一处凹入墙龛，内置褐色陶土罐/花瓶。",
      "右侧可见一个铬合金淋浴装置（竖直管道与混合阀）。",
      "左上角边缘有一丝热带绿植叶片的暗示。"
    ],
    "surfaces": "潮湿、有反光的石材和铬合金表面。"
  },
  "camera": {
    "shot_type": "中景，构图从头顶到大腿上部。",
    "angle": "与视线齐平或略微低角度，强调上半身的体量感。",
    "focus": "主体对焦清晰，尤以躯干与面部为主，景深合理，保持后墙清晰但为次要元素。",
    "lens": "50mm 至 85mm 肖像焦距，以避免畸变并保持体积感。"
  },
  "lighting": {
    "source": "自然漫射日光，自上方且略偏前左方照射。",
    "quality": "柔和但具方向性，在湿润的胸部上坡、肩膀和锁骨处产生明显高光。",
    "shadows": "胸部下方的自然遮蔽阴影，勾勒出腹肌，以及沿颈部/下颌线的阴影。",
    "atmosphere": "湿润、清新。"
  },
  "mood_and_expression": {
    "vibe": "抓拍式、感性、未经摆拍的快照质感。",
    "expression": "神情中性、放松，对镜头并不在意（望向别处）。",
    "action": "正在调整衣物。"
  },
  "style_and_realism": {
    "aesthetic": "照片写实，高度还原、纹理丰富。",
    "texture_focus": "湿润皮肤、紧贴的湿布、滴水和石材纹理。",
    "details": "保留头发的明显湿感及比基尼布料上的特定张力褶皱。"
  },
  "colors_and_tone": {
    "palette": "中性大地色调（米色、棕褐色、棕色背景）、纯白（比基尼）、暖金色肤色。",
    "contrast": "中高对比以突出湿润皮肤的高光与肌肉线条。",
    "white_balance": "自然日光，略偏暖。"
  },
  "quality_and_technical_details": {
    "resolution": "8k，杰作。",
    "noise": "低 ISO，细腻颗粒以增强真实感。"
  },
  "aspect_ratio_and_output": {
    "ratio": "3:4",
    "framing": "竖向构图。"
  },
  "controlnet": {
    "pose_control": {
      "model_type": "DWPose",
      "purpose": "精确骨骼与姿势锁定",
      "constraints": [
        "保留头部向左的侧脸转向",
        "保留双手与比基尼绳子的互动",
        "保持肩宽",
        "保持臀部角度"
      ],
      "recommended_weight": 1.0
    },
    "depth_control": {
      "model_type": "ZoeDepth",
      "purpose": "锁定深度、体积与相机到身体的空间关系",
      "constraints": [
        "保留相对于肋骨的显著胸部前突",
        "保持主体与瓷砖墙之间的分离"
      ],
      "recommended_weight": 0.8
    }
  },
  "negative_prompt": {
    "forbidden_concepts": [
      "看向相机",
      "镜子自拍",
      "拿着手机",
      "皮肤干燥",
      "头发干燥",
      "胸部较小",
      "减少体积感",
      "胸部扁平化",
      "普通比例",
      "动漫风格",
      "卡通",
      "3D 渲染",
      "塑料感皮肤",
      "过度修饰（磨皮）",
      "皮肤平滑处理",
      "对称性",
      "植入物（圆形/高耸型）",
      "规范化解剖",
      "苗条且无肌肉线条的体型"
    ]
  }
}

